import { PIVOTS } from "./parts-face.ts";
import { PROP_PIVOTS } from "./parts-props.ts";

/** A state, named on the figure itself or on the `.av-host` around it. */
const on = (state: string) => `:is(.av,.av-host)[data-state=${state}]`;

/**
 * The stylesheet that moves composed characters: state motion on transform and opacity only,
 * with the pivots the composer leaves out of the markup, because the page forbids inline
 * styles. The static file `characters.css` is this text, generated by
 * `scripts/build-character-css.ts`.
 */
export function characterCss(): string {
	const pivots = Object.entries(PROP_PIVOTS)
		.map(([id, origin]) => `.av [data-prop=${id}]{transform-origin:${origin}}`)
		.join("\n");
	return `/* Generated from src/characters/css.ts by scripts/build-character-css.ts; do not edit. */
/* State motion for composed characters. Put data-state on the <svg class="av"> or on an .av-host around it. */
.av{overflow:visible}
.av .ov{opacity:0}
.av .glow{opacity:.28}
.av .ch,.av .prop,.av .eyes,.av .ov{transform-box:view-box}
.av .ch{transform-origin:${PIVOTS.character}}
.av .eyes{transform-origin:${PIVOTS.eyes};animation:av-blink 5.2s infinite}
.av .o-wait,.av .o-done,.av .o-err{transform-origin:${PIVOTS.badge}}
.av .o-think{transform-origin:${PIVOTS.orbit}}
${pivots}
${on("idle")} .ch{animation:av-breathe 3.8s ease-in-out infinite}
${on("thinking")} .ch{animation:av-tilt 3.2s ease-in-out infinite}
${on("thinking")} .o-think{opacity:1;animation:av-orbit 2.6s linear infinite}
${on("working")} .ch{animation:av-bob .56s ease-in-out infinite}
${on("working")} .prop{animation:av-sweep .56s ease-in-out infinite alternate}
${on("working")} .glow{animation:av-glow .56s ease-in-out infinite alternate}
${on("waiting")} .ch{animation:av-lean 1.6s ease-in-out infinite}
${on("waiting")} .o-wait{opacity:1;animation:av-badge 1.2s ease-in-out infinite}
${on("waiting")} .glow{animation:av-glow 1.2s ease-in-out infinite alternate}
${on("done")} .ch{animation:av-pop .7s cubic-bezier(.3,1.6,.5,1) 1}
${on("done")} .o-done{opacity:1;animation:av-badge-in .5s ease-out 1}
${on("done")} .glow{opacity:.7}
${on("error")} .ch{animation:av-shake .5s ease-in-out 2}
${on("error")} .o-err{opacity:1;animation:av-badge-in .3s ease-out 1}
${on("error")} .ring{stroke:#e5484d}
${on("error")} .glow{opacity:0}
${on("sleepy")} .ch{animation:av-breathe 6s ease-in-out infinite}
${on("sleepy")} .o-zz{opacity:1;animation:av-float 3s ease-in-out infinite}
${on("sleepy")} .glow{opacity:.08}
@keyframes av-blink{0%,93%,100%{transform:scaleY(1)}96%{transform:scaleY(.08)}}
@keyframes av-breathe{0%,100%{transform:scale(1,1)}50%{transform:scale(1.012,1.03)}}
@keyframes av-tilt{0%,100%{transform:rotate(-3deg)}50%{transform:rotate(3deg)}}
@keyframes av-orbit{to{transform:rotate(360deg)}}
@keyframes av-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-2.4px)}}
@keyframes av-sweep{from{transform:rotate(-9deg)}to{transform:rotate(9deg)}}
@keyframes av-glow{from{opacity:.2}to{opacity:.85}}
@keyframes av-lean{0%,100%{transform:rotate(-1deg) translateY(0)}50%{transform:rotate(-6deg) translateY(1px)}}
@keyframes av-badge{0%,100%{transform:scale(1)}50%{transform:scale(1.14)}}
@keyframes av-badge-in{from{transform:scale(.2);opacity:0}to{transform:scale(1);opacity:1}}
@keyframes av-pop{0%{transform:scale(1)}40%{transform:scale(1.1,.94)}70%{transform:scale(.97,1.05)}100%{transform:scale(1)}}
@keyframes av-shake{0%,100%{transform:translateX(0)}20%{transform:translateX(-2.4px)}40%{transform:translateX(2.4px)}60%{transform:translateX(-1.6px)}80%{transform:translateX(1.6px)}}
@keyframes av-float{0%,100%{transform:translateY(0);opacity:.35}50%{transform:translateY(-4px);opacity:1}}
@media (prefers-reduced-motion:reduce){.av *{animation:none!important}.av .o-think{opacity:0!important}}
.av.static *{animation:none!important}
`;
}
